/**
 * @suppress
 */
public object FfiConverterTypeHistoryManager: FfiConverter<HistoryManager, Long> {
    override fun lower(value: HistoryManager): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): HistoryManager {
        return HistoryManager(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): HistoryManager {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: HistoryManager) = 8UL

    override fun write(value: HistoryManager, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



